SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE IF NOT EXISTS admin_roles (user_id BIGINT UNSIGNED NOT NULL,role ENUM('owner','admin','moderator','support') NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id),CONSTRAINT fk_admin_roles_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_used_at DATETIME NULL,PRIMARY KEY(id),UNIQUE KEY uq_admin_token_hash(token_hash),KEY idx_admin_sessions_user(user_id,expires_at),CONSTRAINT fk_admin_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,admin_user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,target_type VARCHAR(40) NULL,target_id BIGINT UNSIGNED NULL,details JSON NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_admin_audit_created(created_at),KEY idx_admin_audit_target(target_type,target_id),CONSTRAINT fk_admin_audit_user FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_user_archive (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,snapshot JSON NOT NULL,reason VARCHAR(500) NOT NULL DEFAULT '',archived_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_admin_archive_user(user_id,created_at),CONSTRAINT fk_admin_archive_admin FOREIGN KEY(archived_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS post_comments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,post_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body VARCHAR(1000) NOT NULL,is_deleted TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_post_comments_post(post_id,is_deleted,created_at),KEY idx_post_comments_user(user_id,created_at),CONSTRAINT fk_post_comments_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,CONSTRAINT fk_post_comments_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE posts ADD COLUMN comments_enabled TINYINT(1) NOT NULL DEFAULT 1;
ALTER TABLE posts ADD COLUMN likes_count_override INT UNSIGNED NULL DEFAULT NULL;
ALTER TABLE reports ADD COLUMN target_type ENUM('user','post','comment','conversation') NOT NULL DEFAULT 'user';
ALTER TABLE reports ADD COLUMN target_id BIGINT UNSIGNED NULL;
ALTER TABLE reports ADD COLUMN is_read TINYINT(1) NOT NULL DEFAULT 0;
ALTER TABLE reports ADD COLUMN admin_note VARCHAR(1000) NULL;
ALTER TABLE reports ADD KEY idx_reports_target(target_type,target_id);
ALTER TABLE reports ADD KEY idx_reports_read_status(is_read,status,created_at);
-- Promote existing account: INSERT INTO admin_roles(user_id,role,is_active) SELECT id,'owner',1 FROM users WHERE username='YOUR_USERNAME' ON DUPLICATE KEY UPDATE role='owner',is_active=1;
